$lines = Get-Content result1.csv
for ($i = 0; $i -lt [Math]::Min(150, $lines.Length); $i++) {
    if ($lines[$i] -match 'PRIORITAS|INFORMASI|FAIR HADIAH|FAIR TEBUS') {
