args.Content:
import openpyxl

wb = openpyxl.load_workbook('spreadsheet.xlsx', data_only=False)
ws = wb['Result Refference ']

print("=== FULFILLMENT SALES HEADERS (113) ===")
for c in range(1, 45):
    val = ws.cell(113, c).value
    if val:
        print(f"{openpyxl.utils.get_column_letter(c)}: {val}")

print("\n=== REFUND HEADERS (136) ===")
for c in range(1, 45):
    val = ws.cell(136, c).value
    if val:
        print(f"{openpyxl.utils.get_column_letter(c)}: {val}")

/**
 * Models.gs
 * Definisi kelas data model untuk sistem simulasi perhitungan promosi dan refund.
 */

class Product {
  constructor(plu, name, price, fracKrt, priceKrt, benefitRp, benefitPct) {
    this.plu = String(plu).trim();
    this.name = name || '';
    this.price = Number(price) || 0;
    this.fracKrt = Number(fracKrt) || 0;
    this.priceKrt = Number(priceKrt) || 0;
    this.benefitRp = Number(benefitRp) || 0;
    this.benefitPct = Number(benefitPct) || 0;
  }
}

class PromoRule {
  constructor(data) {
    this.type = (data.type || '').trim();
    this.code = (data.code || '').trim();
    this.qtyMin = data.qtyMin !== undefined && data.qtyMin !== '' ? Number(data.qtyMin) : null;
    this.rpMin = data.rpMin !== undefined && data.rpMin !== '' ? Number(data.rpMin) : null;
    this.pctBenefit = data.pctBenefit !== undefined && data.pctBenefit !== '' ? Number(data.pctBenefit) : null;
    this.rpBenefit = data.rpBenefit !== undefined && data.rpBenefit !== '' ? Number(data.rpBenefit) : null;
    this.ptBenefit = data.ptBenefit !== undefined && data.ptBenefit !== '' ? Number(data.ptBenefit) : null;
    this.targetItem = (data.targetItem || '').toString().trim();
    this.pluSyarat = (data.pluSyarat || '').toString().trim();
    this.campur = (data.campur || 'N').toString().trim().toUpperCase();
    this.kelipatan = (data.kelipatan || 'Y').toString().trim().toUpperCase();
    this.qtyMax = data.qtyMax !== undefined && data.qtyMax !== '' ? Number(data.qtyMax) : null;
    this.rpMax = data.rpMax !== undefined && data.rpMax !== '' ? Number(data.rpMax) : null;
    this.sourceRow = data.sourceRow || 0;
    this.resultRow = 0; // Baris pada tabel Tipe Promo di Result tab
  }

  getPluSyaratList() {
    if (!this.pluSyarat || this.pluSyarat.toLowerCase() === 'all plu') return [];
    return this.pluSyarat.split(/[\n,\/]+/).map(p => p.trim()).filter(Boolean);
  }

  isAllPlu() {
    return this.pluSyarat.toLowerCase().includes('all plu');
  }
}

class TransactionItem {
  constructor(id, packet, plu, qtyBeli, qtyAktual, isKarton) {
    this.id = id;
    this.packet = (packet || '').trim();
    this.plu = String(plu).trim();
    this.name = '';
    this.price = 0;
    this.qtyBeli = Number(qtyBeli) || 0;
    this.qtyAktual = qtyAktual !== undefined && qtyAktual !== '' ? Number(qtyAktual) : 0;
    this.isKarton = (isKarton || 'N').toString().trim().toUpperCase() === 'Y';
  }
}

class EditOrderRow {
  constructor(plu, name, qtyBeli, qtyStok, qtyRefund) {
    this.plu = String(plu).trim();
    this.name = name || '';
    this.qtyBeli = Number(qtyBeli) || 0;
    this.qtyStok = Number(qtyStok) || 0;
    this.qtyRefund = Number(qtyRefund) || 0;
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { Product, PromoRule, TransactionItem, EditOrderRow };
}

/**
 * DataLoader.gs
 * Bertanggung jawab memuat dan memvalidasi data dari tab 'PLU Master' dan 'Input'.
 */

class DataLoader {
  constructor(spreadsheet) {
    this.ss = spreadsheet || SpreadsheetApp.getActiveSpreadsheet();
    this.productsMap = new Map();
    this.promoRules = [];
    this.transactions = [];
  }

  loadAll() {
    this.loadPluMaster();
    this.loadInputSheet();
    this.validate();
    return {
      productsMap: this.productsMap,
      promoRules: this.promoRules,
      transactions: this.transactions
    };
  }

  loadPluMaster() {
    const sheet = this.ss.getSheetByName('PLU Master');
    if (!sheet) {
      throw new Error("Tab 'PLU Master' tidak ditemukan di spreadsheet.");
    }

    const lastRow = sheet.getLastRow();
    if (lastRow < 2) {
      throw new Error("Tab 'PLU Master' kosong atau tidak memiliki data.");
    }

    // Header at row 1, data starts row 2. Columns: No (1), PLU (2), Nama Produk (3), Harga (4), FRAC_KRT (5), PRICE_KRT (6), ...
    const data = sheet.getRange(2, 1, lastRow - 1, 9).getValues();
    for (let i = 0; i < data.length; i++) {
      const row = data[i];
      const rawPlu = row[1];
      if (rawPlu !== null && rawPlu !== undefined && String(rawPlu).trim() !== '') {
        const plu = String(rawPlu).trim();
        const product = new Product(
          plu,
          row[2], // Nama Produk
          row[3], // Harga
          row[4], // FRAC_KRT
          row[5], // PRICE_KRT
          row[7], // Benefit Rp
          row[8]  // Benefit %
        );
        this.productsMap.set(plu, product);
      }
    }
  }

  loadInputSheet() {
    const sheet = this.ss.getSheetByName('Input');
    if (!sheet) {
      throw new Error("Tab 'Input' tidak ditemukan di spreadsheet.");
    }

    const lastRow = sheet.getLastRow();
    const lastCol = Math.max(sheet.getLastColumn(), 15);
    if (lastRow < 3) {
      throw new Error("Tab 'Input' tidak memiliki data yang cukup.");
    }

    const data = sheet.getRange(1, 1, lastRow, lastCol).getValues();

    // 1. Parsing KODE PROMOSI INPUT
    let promoHeaderRow = -1;
    let promoColMap = {};

    for (let r = 0; r < data.length; r++) {
      for (let c = 0; c < data[r].length; c++) {
        const cell = String(data[r][c] || '').trim().toLowerCase();
        if (cell === 'kode promo') {
          promoHeaderRow = r;
          break;
        }
      }
      if (promoHeaderRow !== -1) break;
    }

    if (promoHeaderRow !== -1) {
      const headerRowVals = data[promoHeaderRow];
      for (let c = 0; c < headerRowVals.length; c++) {
        const h = String(headerRowVals[c] || '').trim().toLowerCase();
        if (h.includes('tipe promo')) promoColMap.tipe = c;
        else if (h.includes('kode promo')) promoColMap.kode = c;
        else if (h.includes('qty min')) promoColMap.qtyMin = c;
        else if (h.includes('rp min')) promoColMap.rpMin = c;
        else if (h.includes('% benefit')) promoColMap.pctBenefit = c;
        else if (h.includes('rp benefit')) promoColMap.rpBenefit = c;
        else if (h.includes('poin') || h.includes('stamp benefit')) promoColMap.ptBenefit = c;
        else if (h.includes('item target')) promoColMap.targetItem = c;
        else if (h.includes('plu syarat')) promoColMap.pluSyarat = c;
        else if (h.includes('campur')) promoColMap.campur = c;
        else if (h.includes('kelipatan')) promoColMap.kelipatan = c;
        else if (h.includes('qty  max') || h.includes('qty max')) promoColMap.qtyMax = c;
        else if (h.includes('rp  max') || h.includes('rp max')) promoColMap.rpMax = c;
      }
      if (promoColMap.tipe === undefined && promoColMap.kode > 0) {
        promoColMap.tipe = promoColMap.kode - 1; // Default kolom Tipe berada sebelum Kode Promo
      }

      let currentTipe = '';
      for (let r = promoHeaderRow + 1; r < data.length; r++) {
        const row = data[r];
        const rowText = row.join(' ').toLowerCase();
        if (rowText.includes('transaction & refund input') || rowText.includes('transaction input')) {
          break; // Selesai tabel promosi
        }

        const kodeVal = promoColMap.kode !== undefined ? String(row[promoColMap.kode] || '').trim() : '';
        const tipeVal = promoColMap.tipe !== undefined ? String(row[promoColMap.tipe] || '').trim() : '';
        if (tipeVal) currentTipe = tipeVal;

        if (kodeVal) {
          const promoRule = new PromoRule({
            type: currentTipe,
            code: kodeVal,
            qtyMin: promoColMap.qtyMin !== undefined ? row[promoColMap.qtyMin] : null,
            rpMin: promoColMap.rpMin !== undefined ? row[promoColMap.rpMin] : null,
            pctBenefit: promoColMap.pctBenefit !== undefined ? row[promoColMap.pctBenefit] : null,
            rpBenefit: promoColMap.rpBenefit !== undefined ? row[promoColMap.rpBenefit] : null,
            ptBenefit: promoColMap.ptBenefit !== undefined ? row[promoColMap.ptBenefit] : null,
            targetItem: promoColMap.targetItem !== undefined ? row[promoColMap.targetItem] : '',
            pluSyarat: promoColMap.pluSyarat !== undefined ? row[promoColMap.pluSyarat] : '',
            campur: promoColMap.campur !== undefined ? row[promoColMap.campur] : 'N',
            kelipatan: promoColMap.kelipatan !== undefined ? row[promoColMap.kelipatan] : 'Y',
            qtyMax: promoColMap.qtyMax !== undefined ? row[promoColMap.qtyMax] : null,
            rpMax: promoColMap.rpMax !== undefined ? row[promoColMap.rpMax] : null,
            sourceRow: r + 1
          });
          this.promoRules.push(promoRule);
        }
      }
    }

    // 2. Parsing TRANSACTION & REFUND INPUT
    let txHeaderRow = -1;
    let txColMap = {};

    for (let r = 0; r < data.length; r++) {
      const rowText = data[r].join(' ').toLowerCase();
      if (rowText.includes('transaction & refund input') || rowText.includes('transaction input')) {
        // Cari header row tepat setelah baris judul section
        for (let subR = r + 1; subR < Math.min(r + 6, data.length); subR++) {
          for (let c = 0; c < data[subR].length; c++) {
            const cell = String(data[subR][c] || '').trim().toLowerCase();
            if (cell === 'plu') {
              txHeaderRow = subR;
              break;
            }
          }
          if (txHeaderRow !== -1) break;
        }
        break;
      }
    }

    if (txHeaderRow !== -1) {
      const headerRowVals = data[txHeaderRow];
      for (let c = 0; c < headerRowVals.length; c++) {
        const h = String(headerRowVals[c] || '').trim().toLowerCase();
        if (h.includes('paket')) txColMap.paket = c;
        else if (h === 'plu') txColMap.plu = c;
        else if (h.includes('qty beli')) txColMap.qtyBeli = c;
        else if (h.includes('qty aktual')) txColMap.qtyAktual = c;
        else if (h.includes('karton')) txColMap.karton = c;
      }
      if (txColMap.paket === undefined && txColMap.plu > 0) {
        txColMap.paket = txColMap.plu - 1;
      }

      let currentPaket = 'Non-Paket';
      let itemId = 1;

      for (let r = txHeaderRow + 1; r < data.length; r++) {
        const row = data[r];
        const rawPlu = txColMap.plu !== undefined ? row[txColMap.plu] : null;
        const rawPaket = txColMap.paket !== undefined ? String(row[txColMap.paket] || '').trim() : '';

        // Jika baris berisi judul kategori hadiah/tebus murah tanpa PLU
        if (rawPaket && (!rawPlu || String(rawPlu).trim() === '')) {
          currentPaket = rawPaket;
          continue;
        }

        if (rawPaket) {
          currentPaket = rawPaket;
        }

        if (rawPlu !== null && rawPlu !== undefined && String(rawPlu).trim() !== '') {
          const plu = String(rawPlu).trim();
          const qtyBeli = txColMap.qtyBeli !== undefined ? row[txColMap.qtyBeli] : 0;
          const qtyAktual = txColMap.qtyAktual !== undefined ? row[txColMap.qtyAktual] : 0;
          const isKarton = txColMap.karton !== undefined ? row[txColMap.karton] : 'N';

          const item = new TransactionItem(
            itemId++,
            currentPaket,
            plu,
            qtyBeli,
            qtyAktual,
            isKarton
          );

          // Pasangkan info dari PLU Master
          const prod = this.productsMap.get(plu);
          if (prod) {
            item.name = prod.name;
            item.price = prod.price;
          }

          this.transactions.push(item);
        }
      }
    }
  }

  validate() {
    if (this.promoRules.length === 0) {
      throw new Error("Tidak ditemukan aturan promosi yang valid pada tab 'Input'.");
    }

    if (this.transactions.length === 0) {
      throw new Error("Tidak ditemukan item transaksi pada bagian 'TRANSACTION & REFUND INPUT' di tab 'Input'.");
    }

    // Validasi PLU
    for (const item of this.transactions) {
      if (!this.productsMap.has(item.plu)) {
        throw new Error(`PLU '${item.plu}' pada transaksi (${item.packet}) tidak terdaftar di tab 'PLU Master'.`);
      }
      if (item.qtyBeli < 0) {
        throw new Error(`Qty Beli untuk PLU '${item.plu}' tidak boleh bernilai negatif.`);
      }
      if (item.qtyAktual < 0) {
        throw new Error(`Qty Aktual untuk PLU '${item.plu}' tidak boleh bernilai negatif.`);
      }
      if (item.qtyAktual > item.qtyBeli) {
        throw new Error(`Qty Aktual (${item.qtyAktual}) untuk PLU '${item.plu}' tidak boleh melebihi Qty Beli (${item.qtyBeli}).`);
      }
    }
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { DataLoader };
}

/**
 * QtyDistributionService.gs
 * Bertanggung jawab mendistribusikan total Qty Aktual / Stok fisik per PLU
 * ke masing-masing baris transaksi berdasarkan urutan prioritas pemenuhan:
 * 1. Bundling
 * 2. Hadiah PHG
 * 3. Non-Paket / Upsell
 * 4. Fair Hadiah
 * 5. Fair Tebus Murah
 */

class QtyDistributionService {
  constructor() {}

  /**
   * Menentukan kategori prioritas dari nama paket.
   * Nilai return lebih kecil berarti prioritas lebih tinggi.
   */
  static getPacketPriority(packetName) {
    const p = (packetName || '').toLowerCase();
    if (p.includes('bundling')) return 1;
    if (p.includes('hadiah phg') || p.includes('phg')) return 2;
    if (p.includes('non-paket') || p.includes('upsell') || p === '') return 3;
    if (p.includes('fair hadiah')) return 4;
    if (p.includes('tebus murah') || p.includes('tmh')) return 5;
    return 6;
  }

  /**
   * Mendistribusikan total stok per PLU ke baris-baris transaksi.
   * @param {Array<TransactionItem>} transactions 
   * @param {Map<string, number>} stockPerPluMap - Map berisi plu -> total Qty Stok
   * @returns {Array<TransactionItem>} transactions yang telah diperbarui qtyAktual-nya
   */
  distributeStock(transactions, stockPerPluMap) {
    // Salin stok agar tidak memodifikasi input asli langsung
    const remainingStock = new Map();
    for (const [plu, stock] of stockPerPluMap.entries()) {
      remainingStock.set(String(plu).trim(), Number(stock) || 0);
    }

    // Kelompokkan item berdasarkan prioritas paket
    const prioritizedIndices = transactions.map((item, idx) => ({
      index: idx,
      priority: QtyDistributionService.getPacketPriority(item.packet),
      plu: item.plu,
      qtyBeli: item.qtyBeli
    })).sort((a, b) => a.priority - b.priority);

    // Reset qtyAktual pada semua item
    for (const item of transactions) {
      item.qtyAktual = 0;
    }

    // Alokasikan stok sesuai prioritas
    for (const entry of prioritizedIndices) {
      const item = transactions[entry.index];
      const available = remainingStock.get(item.plu) || 0;
      if (available <= 0) {
        item.qtyAktual = 0;
      } else if (available >= item.qtyBeli) {
        item.qtyAktual = item.qtyBeli;
        remainingStock.set(item.plu, available - item.qtyBeli);
      } else {
        item.qtyAktual = available;
        remainingStock.set(item.plu, 0);
      }
    }

    return transactions;
  }

  /**
   * Menghasilkan ringkasan Edit Order per PLU dari daftar transaksi.
   * @param {Array<TransactionItem>} transactions
   * @param {Map<string, Product>} productsMap
   * @returns {Array<EditOrderRow>}
   */
  buildEditOrderSummary(transactions, productsMap) {
    const summaryMap = new Map();

    for (const item of transactions) {
      if (!summaryMap.has(item.plu)) {
        const prod = productsMap ? productsMap.get(item.plu) : null;
        summaryMap.set(item.plu, {
          plu: item.plu,
          name: prod ? prod.name : item.name,
          qtyBeli: 0,
          qtyStok: 0
        });
      }
      const entry = summaryMap.get(item.plu);
      entry.qtyBeli += item.qtyBeli;
      entry.qtyStok += item.qtyAktual;
    }

    const result = [];
    for (const entry of summaryMap.values()) {
      const qtyRefund = Math.max(0, entry.qtyBeli - entry.qtyStok);
      result.push(new EditOrderRow(
        entry.plu,
        entry.name,
        entry.qtyBeli,
        entry.qtyStok,
        qtyRefund
      ));
    }

    return result;
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { QtyDistributionService };
}

/**
 * KartonanService.gs
 * Menghasilkan formula perhitungan diskon kartonan dan net sales after karton.
 */

class KartonanService {
  constructor() {}

  /**
   * Menghasilkan formula diskon karton untuk suatu baris transaksi.
   * @param {string} pluCell - Contoh 'B70'
   * @param {string} qtyCell - Contoh 'E70'
   * @param {boolean} isKarton - Apakah item ini berstatus kartonan
   * @returns {string} Formula atau angka '0'
   */
  buildDiskonKartonFormula(pluCell, qtyCell, isKarton) {
    if (!isKarton) {
      return '=0';
    }
    // FRAC_KRT ada di kolom E (indeks 4 dari B), Diskon Karton (Benefit Rp) ada di kolom H (indeks 7 dari B)
    return `=IFERROR(ROUNDDOWN(${qtyCell}/VLOOKUP(${pluCell},'PLU Master'!$B:$E,4,FALSE),0)*VLOOKUP(${pluCell},'PLU Master'!$B:$H,7,FALSE),0)`;
  }

  /**
   * Menghasilkan formula Net Sales After Karton: Gross Sales - Diskon Karton.
   * @param {string} grossCell - Contoh 'F70'
   * @param {string} kartonCell - Contoh 'G70'
   * @returns {string}
   */
  buildNetAfterKartonFormula(grossCell, kartonCell) {
    return `=${grossCell}-${kartonCell}`;
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { KartonanService };
}

/**
 * BundlingService.gs
 * Menghasilkan formula perhitungan diskon paket bundling dan prorata pembagian nilai ke tiap PLU.
 */

class BundlingService {
  constructor() {}

  /**
   * Menghasilkan formula nilai total diskon bundling pada baris pertama paket.
   * @param {PromoRule} promoRule
   * @param {string} promoRefCell - Sel benefit pada tabel Tipe Promo (misal 'D7' untuk % atau 'E10' untuk Rp)
   * @param {string} grossRange - Range gross sales paket, misal 'F74:F76'
   * @returns {string}
   */
  buildTotalDiscountFormula(promoRule, promoRefCell, grossRange) {
    if (promoRule.pctBenefit) {
      return `=CEILING(${promoRefCell}*SUM(${grossRange}),100)`;
    } else if (promoRule.rpBenefit) {
      return `=${promoRefCell}`;
    }
    return '=0';
  }

  /**
   * Menghasilkan formula prorata diskon bundling per PLU.
   * @param {boolean} isLastItemInPackage - Apakah item ini item terakhir dalam paket
   * @param {string} currentGrossCell - Misal 'F74'
   * @param {string} packageGrossRangeAbsolute - Misal '$F$74:$F$76'
   * @param {string} totalBundlingCellAbsolute - Misal '$I$74'
   * @param {string} prevProrateSumRange - Misal 'J74:J75' untuk item terakhir
   * @returns {string}
   */
  buildProrateFormula(isLastItemInPackage, currentGrossCell, packageGrossRangeAbsolute, totalBundlingCellAbsolute, prevProrateSumRange) {
    if (isLastItemInPackage) {
      const cleanTotalCell = totalBundlingCellAbsolute.replace(/\$/g, '');
      return `=${cleanTotalCell}-SUM(${prevProrateSumRange})`;
    }
    return `=IFERROR(ROUND(${currentGrossCell}/SUM(${packageGrossRangeAbsolute})*${totalBundlingCellAbsolute},0),0)`;
  }

  /**
   * Formula Net Sales After Bundling: Net After Karton - Bundling / PLU.
   */
  buildNetAfterBundlingFormula(netKartonCell, bundlingPluCell) {
    return `=${netKartonCell}-${bundlingPluCell}`;
  }

  /**
   * Formula Bundling / PLU pada tabel Fulfillment.
   */
  buildFulfillmentBundlingFormula(qtyAktualCell, qtyBeliCell, salesBundlingPluCell) {
    return `=IFERROR(${qtyAktualCell}*(${salesBundlingPluCell}/${qtyBeliCell}),0)`;
  }

  /**
   * Formula Bundling / PLU pada tabel Refund.
   */
  buildRefundBundlingFormula(salesBundlingPluCell, fulfillmentBundlingPluCell) {
    return `=${salesBundlingPluCell}-${fulfillmentBundlingPluCell}`;
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { BundlingService };
}

/**
 * PHGService.gs
 * Menghasilkan formula perhitungan diskon Produk Hadiah Gratis (PHG).
 */

class PHGService {
  constructor() {}

  /**
   * Formula nilai PHG pada tabel SALES: sama dengan Gross Sales produk hadiah.
   * @param {string} grossCell - Misal 'F81'
   */
  buildSalesPHGFormula(grossCell) {
    return `=${grossCell}`;
  }

  /**
   * Formula Net Sales After PHG: Net After Bundling - PHG / PLU.
   */
  buildNetAfterPHGFormula(netBundlingCell, phgPluCell) {
    return `=${netBundlingCell}-${phgPluCell}`;
  }

  /**
   * Formula PHG pada tabel Fulfillment.
   */
  buildFulfillmentPHGFormula(qtyAktualCell, salesPHGPluCell) {
    return `=IF(${qtyAktualCell}>0,${salesPHGPluCell},0)`;
  }

  /**
   * Formula PHG pada tabel Refund.
   */
  buildRefundPHGFormula(salesPHGPluCell, fulfillmentPHGPluCell) {
    return `=${salesPHGPluCell}-${fulfillmentPHGPluCell}`;
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { PHGService };
}

/**
 * HargaCoretService.gs
 * Menghasilkan formula perhitungan diskon promosi Harga Coret (fixed Rp maupun % benefit).
 */

class HargaCoretService {
  constructor() {}

  /**
   * Menghasilkan formula diskon Harga Coret pada tabel SALES.
   * @param {PromoRule} promoRule
   * @param {string} qtyCell - Misal 'E72'
   * @param {string} grossCell - Misal 'F72'
   * @param {string} minQtyCell - Misal 'C34'
   * @param {string} benefitCell - Misal 'E34' (Rp) atau 'D35' (%)
   * @param {string} maxQtyCell - Misal 'L34'
   */
  buildSalesFormula(promoRule, qtyCell, grossCell, minQtyCell, benefitCell, maxQtyCell) {
    if (promoRule.rpBenefit) {
      return `=CEILING(MIN(ROUNDDOWN(SUM(${qtyCell})/${minQtyCell},0),${maxQtyCell})*${benefitCell},100)`;
    } else if (promoRule.pctBenefit) {
      return `=MIN(ROUNDDOWN(SUM(${qtyCell})/${minQtyCell},0)*${minQtyCell},${minQtyCell}*${maxQtyCell})*CEILING((SUM(${grossCell})/SUM(${qtyCell}))*${benefitCell},100)`;
    }
    return '=0';
  }

  /**
   * Menghasilkan formula diskon Harga Coret pada tabel Fulfillment.
   */
  buildFulfillmentFormula(promoRule, qtyAktualCell, grossAktualCell, minQtyCell, benefitCell, maxQtyCell) {
    if (promoRule.rpBenefit) {
      return `=CEILING(MIN(ROUNDDOWN(SUM(${qtyAktualCell})/${minQtyCell},0),${maxQtyCell})*${benefitCell},100)`;
    } else if (promoRule.pctBenefit) {
      return `=IFERROR(MIN(ROUNDDOWN(SUM(${qtyAktualCell})/${minQtyCell},0)*${minQtyCell},${minQtyCell}*${maxQtyCell})*CEILING((SUM(${grossAktualCell})/SUM(${qtyAktualCell}))*${benefitCell},100),0)`;
    }
    return '=0';
  }

  /**
   * Formula Net Sales After Harga Coret: Net After PHG - Harga Coret / PLU.
   */
  buildNetAfterFormula(netPrevCell, coretPluCell) {
    return `=${netPrevCell}-${coretPluCell}`;
  }

  /**
   * Formula Harga Coret pada tabel Refund.
   */
  buildRefundFormula(salesCoretPluCell, fulfillmentCoretPluCell) {
    return `=${salesCoretPluCell}-${fulfillmentCoretPluCell}`;
  }
}

