/**
 * ResultSheetBuilder.gs
 * Bertanggung jawab menyusun seluruh struktur tab Result baru ('Result - 1', 'Result - 2', dst.),
 * menuliskan formula Google Sheets aktif step-by-step, dan menerapkan styling tampilan.
 */

class ResultSheetBuilder {
  constructor(spreadsheet, services) {
    this.ss = spreadsheet || SpreadsheetApp.getActiveSpreadsheet();
    this.services = services || {};
  }

  static getColLetter(colIdx) {
    let temp = '';
    let letter = '';
    while (colIdx > 0) {
      temp = (colIdx - 1) % 26;
      letter = String.fromCharCode(temp + 65) + letter;
      colIdx = Math.floor((colIdx - temp - 1) / 26);
    }
    return letter;
  }

  getNextSheetName() {
    const sheets = this.ss.getSheets();
    let maxNum = 0;
    const regex = /^Result\s*-\s*(\d+)$/i;

    for (const sheet of sheets) {
      const name = sheet.getName();
      const match = name.match(regex);
      if (match) {
        const num = parseInt(match[1], 10);
        if (num > maxNum) maxNum = num;
      }
    }
    return `Result - ${maxNum + 1}`;
  }

  build(promoRules, transactions, editOrderSummary) {
    const newSheetName = this.getNextSheetName();
    const sheet = this.ss.insertSheet(newSheetName);

    // 1. Tulis Header Judul (Baris 2)
    sheet.getRange(2, 1).setValue("SIMULASI PERHITUNGAN ").setFontWeight("bold");
    sheet.getRange(2, 2).setValue("SO").setFontWeight("bold");
    sheet.getRange(3, 2).setValue("SOC");
    sheet.getRange(4, 2).setValue("BA Refund");

    // 2. Tulis Tabel Tipe Promo (Mulai Baris 6)
    const promoStartRow = 6;
    const promoHeaders = [
      "Tipe Promo", "Kode Promo", "Mekanisme Beli", "% Benefit", "Rp Benefit",
      "Poin/Stamp Benefit", "Item Target", "PLU Syarat", "Nama Produk",
      "Campur", "Kelipatan", "Limitasi Max"
    ];

    sheet.getRange(promoStartRow, 1, 1, promoHeaders.length)
      .setValues([promoHeaders])
      .setBackground("#D9D9D9")
      .setFontWeight("bold");

    let currentPromoRow = promoStartRow + 1;
    for (const rule of promoRules) {
      rule.resultRow = currentPromoRow;
      const plus = rule.getPluSyaratList();
      const mainPlu = plus.length > 0 ? plus[0] : (rule.targetItem || '');

      const rowVal = [
        rule.type || '',
        rule.code || '',
        rule.qtyMin !== null ? rule.qtyMin : (rule.rpMin !== null ? rule.rpMin : '-'),
        rule.pctBenefit !== null ? rule.pctBenefit : '-',
        rule.rpBenefit !== null ? rule.rpBenefit : '-',
        rule.ptBenefit !== null ? rule.ptBenefit : '-',
        rule.targetItem || '-',
        rule.pluSyarat || '-',
        mainPlu && !isNaN(Number(mainPlu)) ? `=IFERROR(VLOOKUP(H${currentPromoRow},'PLU Master'!$B:$C, 2, FALSE),"-")` : (rule.isAllPlu() ? "All Produk" : "-"),
        rule.campur || '-',
        rule.kelipatan || '-',
        rule.qtyMax !== null ? rule.qtyMax : (rule.rpMax !== null ? rule.rpMax : '-')
      ];

      sheet.getRange(currentPromoRow, 1, 1, rowVal.length).setValues([rowVal]);
      currentPromoRow++;
    }

    // 3. Konfigurasi Kolom Promosi Dinamis
    const promoColsDef = this.buildPromoColumnsDefinition(promoRules);

    // 4. Bangun Tabel SALES (Order Awal)
    const salesHeaderRow = currentPromoRow + 2;
    sheet.getRange(salesHeaderRow - 1, 1).setValue("SALES").setFontWeight("bold");

    const salesCols = this.buildTableHeaders(promoColsDef, false);
    sheet.getRange(salesHeaderRow, 1, 1, salesCols.length)
      .setValues([salesCols])
      .setBackground("#4A86E8")
      .setFontColor("#FFFFFF")
      .setFontWeight("bold");

    const salesStartRow = salesHeaderRow + 1;
    const salesEndRow = salesStartRow + transactions.length - 1;
    const salesDataFormulas = this.buildSalesFormulas(transactions, promoColsDef, salesStartRow, salesEndRow);

    sheet.getRange(salesStartRow, 1, transactions.length, salesCols.length)
      .setFormulas(salesDataFormulas);

    // Baris Total SALES
    const salesTotalRow = salesEndRow + 1;
    this.buildSalesTotalRow(sheet, salesTotalRow, salesStartRow, salesEndRow, salesCols.length, promoColsDef);

    // 5. Bangun Tabel EDIT ORDER
    const editOrderHeaderRow = salesTotalRow + 3;
    sheet.getRange(editOrderHeaderRow - 1, 1).setValue("EDIT ORDER").setFontWeight("bold");
    const editOrderHeaders = ["PLU", "Judul Produk", "Qty Beli", "Qty Stok", "Qty Refund"];
    sheet.getRange(editOrderHeaderRow, 1, 1, editOrderHeaders.length)
      .setValues([editOrderHeaders])
      .setBackground("#E06666")
      .setFontColor("#FFFFFF")
      .setFontWeight("bold");

    const editOrderStartRow = editOrderHeaderRow + 1;
    const editOrderRows = [];
    for (let i = 0; i < editOrderSummary.length; i++) {
      const r = editOrderStartRow + i;
      const item = editOrderSummary[i];
      editOrderRows.push([
        item.plu,
        `=IFERROR(VLOOKUP(A${r},'PLU Master'!$B:$C, 2, FALSE),"")`,
        `=SUMIF($B$${salesStartRow}:$B$${salesEndRow},A${r},$E$${salesStartRow}:$E$${salesEndRow})`,
        item.qtyStok,
        `=C${r}-D${r}`
      ]);
    }
    if (editOrderRows.length > 0) {
      sheet.getRange(editOrderStartRow, 1, editOrderRows.length, editOrderHeaders.length)
        .setFormulas(editOrderRows.map(row => row.map(v => typeof v === 'string' && v.startsWith('=') ? v : null)))
        .setValues(editOrderRows.map(row => row.map(v => typeof v === 'string' && v.startsWith('=') ? '' : v)));
    }
    const editOrderEndRow = editOrderStartRow + editOrderRows.length - 1;

    // 6. Bangun Tabel Detail Transaksi (Order Awal)
    const detail1HeaderRow = editOrderEndRow + 3;
    const detail1EndRow = this.buildDetailTransaksi1(sheet, detail1HeaderRow, salesTotalRow, salesStartRow, salesEndRow, promoColsDef);

    // 7. Bangun Tabel FULFILLMENT SALES
    const fulfillHeaderRow = detail1EndRow + 3;
    sheet.getRange(fulfillHeaderRow - 1, 1).setValue("FULFILLMENT SALES").setFontWeight("bold");
    const fulfillCols = this.buildTableHeaders(promoColsDef, true);
    sheet.getRange(fulfillHeaderRow, 1, 1, fulfillCols.length)
      .setValues([fulfillCols])
      .setBackground("#6AA84F")
      .setFontColor("#FFFFFF")
      .setFontWeight("bold");

    const fulfillStartRow = fulfillHeaderRow + 1;
    const fulfillEndRow = fulfillStartRow + transactions.length - 1;
    const fulfillDataFormulas = this.buildFulfillmentFormulas(transactions, promoColsDef, fulfillStartRow, fulfillEndRow, salesStartRow, salesEndRow);

    sheet.getRange(fulfillStartRow, 1, transactions.length, fulfillCols.length)
      .setFormulas(fulfillDataFormulas);

    const fulfillTotalRow = fulfillEndRow + 1;
    this.buildFulfillmentTotalRow(sheet, fulfillTotalRow, fulfillStartRow, fulfillEndRow, fulfillCols.length, promoColsDef);

    // 8. Bangun Tabel REFUND
    const refundHeaderRow = fulfillTotalRow + 3;
    sheet.getRange(refundHeaderRow - 1, 1).setValue("REFUND").setFontWeight("bold");
    const refundCols = this.buildRefundTableHeaders(promoColsDef);
    sheet.getRange(refundHeaderRow, 1, 1, refundCols.length)
      .setValues([refundCols])
      .setBackground("#CC0000")
      .setFontColor("#FFFFFF")
      .setFontWeight("bold");

    const refundStartRow = refundHeaderRow + 1;
    const refundEndRow = refundStartRow + transactions.length - 1;
    const refundDataFormulas = this.buildRefundFormulas(transactions, promoColsDef, refundStartRow, refundEndRow, salesStartRow, fulfillStartRow);

    sheet.getRange(refundStartRow, 1, transactions.length, refundCols.length)
      .setFormulas(refundDataFormulas);

    const refundTotalRow = refundEndRow + 1;
    this.buildRefundTotalRow(sheet, refundTotalRow, refundStartRow, refundEndRow, refundCols.length, promoColsDef);

    // 9. Bangun Tabel Detail Transaksi (Pemenuhan & Refund)
    const detail2HeaderRow = refundTotalRow + 3;
    this.buildDetailTransaksi2(sheet, detail2HeaderRow, fulfillTotalRow, refundTotalRow, fulfillStartRow, fulfillEndRow, refundStartRow, refundEndRow, promoColsDef, detail1HeaderRow);

    // 10. Format Tampilan (Borders & Number Formats)
    this.applyFormatting(sheet, salesStartRow, salesEndRow, fulfillStartRow, fulfillEndRow, refundStartRow, refundEndRow, promoColsDef);

    return sheet;
  }

  buildPromoColumnsDefinition(promoRules) {
    const cols = {
      bundling: promoRules.filter(r => r.type.toLowerCase().includes('bundling')),
      phg: promoRules.filter(r => r.type.toLowerCase().includes('phg') || r.type.toLowerCase().includes('produk hadiah')),
      coret: promoRules.filter(r => r.type.toLowerCase().includes('coret')),
      upsell: promoRules.filter(r => r.type.toLowerCase().includes('upsell')),
      fairPotal: promoRules.filter(r => r.type.toLowerCase().includes('fair - potal') || r.type.toLowerCase().includes('fair potal')),
      fairHadiah: promoRules.filter(r => r.type.toLowerCase().includes('fair hadiah')),
      fairTmh: promoRules.filter(r => r.type.toLowerCase().includes('tebus murah') || r.type.toLowerCase().includes('fair tmh')),
      dab: promoRules.filter(r => r.type.toLowerCase().includes('dab') || r.type.toLowerCase().includes('alat bayar')),
      points: promoRules.filter(r => r.type.toLowerCase().includes('poin')),
      stamps: promoRules.filter(r => r.type.toLowerCase().includes('stamp'))
    };
    return cols;
  }

  buildTableHeaders(promoColsDef, isFulfillment) {
    const headers = [
      "Paket", "PLU", "Judul Produk", "Harga", "Qty"
    ];
    if (isFulfillment) {
      headers.push("Qty Aktual");
    }
    headers.push("Gross Sales", "Diskon Karton", "Net Sales After Karton");

    if (promoColsDef.bundling.length > 0) {
      if (!isFulfillment) headers.push("Bundling");
      headers.push("Bundling / PLU", "Net Sales After Bundling");
    }
    if (promoColsDef.phg.length > 0) {
      if (!isFulfillment) headers.push("PHG");
      headers.push("PHG/PLU", "Net Sales After PHG");
    }
    if (promoColsDef.coret.length > 0) {
      if (!isFulfillment) headers.push(`Harga Coret ${promoColsDef.coret.map(r => r.code).join(', ')}`);
      headers.push("Harga Coret / PLU", "Nett Sales After Harga Coret");
    }
    for (const up of promoColsDef.upsell) {
      headers.push(`Upsell ${up.code}`, "Upsell / PLU", "Net Sales After Upsell");
    }
    for (const pot of promoColsDef.fairPotal) {
      headers.push(`Fair Potal ${pot.code}`, "Fair Potal / PLU", "Net Sales After Fair Potal");
    }
    if (promoColsDef.fairTmh.length > 0 || promoColsDef.fairHadiah.length > 0) {
      if (!isFulfillment) headers.push("Fair TMH");
      headers.push("Fair TMH/PLU", "Net Sales After Fair TMH");
    }
    for (const d of promoColsDef.dab) {
      headers.push(`Diskon Alat Bayar ${d.code}`, "Diskon Alat Bayar/PLU", "Net Sales After Diskon Alat Bayar");
    }
    for (const pt of promoColsDef.points) {
      headers.push(`Point Received\n${pt.code}`);
    }
    for (const st of promoColsDef.stamps) {
      headers.push(`Stamp Received\n${st.code}`);
    }
    return headers;
  }

  buildRefundTableHeaders(promoColsDef) {
    const headers = [
      "Paket", "PLU", "Judul Produk", "Harga", "Qty", "Qty Refund",
      "Gross Sales", "Diskon Karton", "Net Sales After Karton"
    ];
    if (promoColsDef.bundling.length > 0) {
      headers.push("Bundling / PLU", "Net Sales After Bundling");
    }
    if (promoColsDef.phg.length > 0) {
      headers.push("PHG/PLU", "Net Sales After PHG");
    }
    if (promoColsDef.coret.length > 0) {
      headers.push("Harga Coret / PLU", "Nett Sales After Harga Coret");
    }
    for (const up of promoColsDef.upsell) {
      headers.push(`Upsell ${up.code}`, "Upsell / PLU", "Net Sales After Upsell");
    }
    for (const pot of promoColsDef.fairPotal) {
      headers.push(`Fair Potal ${pot.code}`, "Fair Potal / PLU", "Net Sales After Fair Potal");
    }
    if (promoColsDef.fairTmh.length > 0 || promoColsDef.fairHadiah.length > 0) {
      headers.push("Fair TMH/PLU", "Net Sales After Fair TMH");
    }
    for (const d of promoColsDef.dab) {
      headers.push(`Diskon Alat Bayar ${d.code}`, "Diskon Alat Bayar/PLU", "Net Sales After Diskon Alat Bayar");
    }
    for (const pt of promoColsDef.points) {
      headers.push(`Point Received\n${pt.code}`);
    }
    for (const st of promoColsDef.stamps) {
      headers.push(`Stamp Received\n${st.code}`);
    }
    return headers;
  }

  buildSalesFormulas(transactions, promoColsDef, startRow, endRow) {
    const formulas = [];

    for (let i = 0; i < transactions.length; i++) {
      const r = startRow + i;
      const item = transactions[i];
      const rowFormulas = [];

      let colIdx = 1;
      // Col 1: Paket, Col 2: PLU
      rowFormulas.push(item.packet); colIdx++;
      rowFormulas.push(item.plu); colIdx++;
      // Col 3: Judul Produk
      rowFormulas.push(`=IFERROR(VLOOKUP(B${r},'PLU Master'!$B:$C, 2, FALSE),"")`); colIdx++;
      // Col 4: Harga
      rowFormulas.push(`=IFERROR(VLOOKUP(B${r},'PLU Master'!$B:$D, 3, FALSE),0)`); colIdx++;
      // Col 5: Qty
      rowFormulas.push(item.qtyBeli); colIdx++;
      // Col 6: Gross Sales (F)
      rowFormulas.push(`=D${r}*E${r}`); colIdx++;
      // Col 7: Diskon Karton (G)
      rowFormulas.push(this.services.kartonan.buildDiskonKartonFormula(`B${r}`, `E${r}`, item.isKarton)); colIdx++;
      // Col 8: Net After Karton (H)
      rowFormulas.push(this.services.kartonan.buildNetAfterKartonFormula(`F${r}`, `G${r}`)); colIdx++;

      let lastNetCol = 'H';

      // Bundling (I, J, K)
      if (promoColsDef.bundling.length > 0) {
        const isBundling = item.packet.toLowerCase().includes('bundling');
        const bundlingTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const bundlingPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netBundlingCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        if (isBundling) {
          // Cari range baris untuk paket bundling ini
          const pkgIndices = [];
          for (let j = 0; j < transactions.length; j++) {
            if (transactions[j].packet === item.packet) pkgIndices.push(startRow + j);
          }
          const pkgFirstRow = pkgIndices[0];
          const pkgLastRow = pkgIndices[pkgIndices.length - 1];
          const matchedRule = promoColsDef.bundling.find(b => item.packet.includes(b.code)) || promoColsDef.bundling[0];
          const benefitRef = matchedRule.pctBenefit ? `D${matchedRule.resultRow}` : `E${matchedRule.resultRow}`;

          if (r === pkgFirstRow) {
            rowFormulas.push(this.services.bundling.buildTotalDiscountFormula(matchedRule, benefitRef, `F${pkgFirstRow}:F${pkgLastRow}`));
          } else {
            rowFormulas.push('=0');
          }
          colIdx++;

          const isLast = (r === pkgLastRow);
          const prevRange = `${bundlingPluCol}${pkgFirstRow}:${bundlingPluCol}${r - 1}`;
          rowFormulas.push(this.services.bundling.buildProrateFormula(
            isLast,
            `F${r}`,
            `$F$${pkgFirstRow}:$F$${pkgLastRow}`,
            `$${bundlingTotalCol}$${pkgFirstRow}`,
            prevRange
          ));
          colIdx++;
        } else {
          rowFormulas.push('=0'); colIdx++;
          rowFormulas.push('=0'); colIdx++;
        }
        rowFormulas.push(this.services.bundling.buildNetAfterBundlingFormula(`${lastNetCol}${r}`, `${bundlingPluCol}${r}`)); colIdx++;
        lastNetCol = netBundlingCol;
      }

      // PHG (L, M, N)
      if (promoColsDef.phg.length > 0) {
        const isPHG = item.packet.toLowerCase().includes('phg') || item.packet.toLowerCase().includes('hadiah phg');
        const phgTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const phgPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netPHGCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        if (isPHG) {
          rowFormulas.push(this.services.phg.buildSalesPHGFormula(`F${r}`)); colIdx++;
          rowFormulas.push(`=${phgTotalCol}${r}`); colIdx++;
        } else {
          rowFormulas.push('=0'); colIdx++;
          rowFormulas.push('=0'); colIdx++;
        }
        rowFormulas.push(this.services.phg.buildNetAfterPHGFormula(`${lastNetCol}${r}`, `${phgPluCol}${r}`)); colIdx++;
        lastNetCol = netPHGCol;
      }

      // Harga Coret (O, P, Q)
      if (promoColsDef.coret.length > 0) {
        const coretTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const coretPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netCoretCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        const matchedCoret = promoColsDef.coret.find(c => c.getPluSyaratList().includes(item.plu));
        if (matchedCoret) {
          const benefitRef = matchedCoret.rpBenefit ? `E${matchedCoret.resultRow}` : `D${matchedCoret.resultRow}`;
          rowFormulas.push(this.services.hargaCoret.buildSalesFormula(
            matchedCoret,
            `E${r}`,
            `F${r}`,
            `C${matchedCoret.resultRow}`,
            benefitRef,
            `L${matchedCoret.resultRow}`
          ));
          colIdx++;
          rowFormulas.push(`=${coretTotalCol}${r}`); colIdx++;
        } else {
          rowFormulas.push('=0'); colIdx++;
          rowFormulas.push('=0'); colIdx++;
        }
        rowFormulas.push(this.services.hargaCoret.buildNetAfterFormula(`${lastNetCol}${r}`, `${coretPluCol}${r}`)); colIdx++;
        lastNetCol = netCoretCol;
      }

      // Upsell
      for (const up of promoColsDef.upsell) {
        const upTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const upPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netUpCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        const isEligible = up.getPluSyaratList().includes(item.plu);
        const benefitRef = up.rpBenefit ? `E${up.resultRow}` : `D${up.resultRow}`;

        if (up.campur === 'Y') {
          // Cari baris-baris eligible
          const eligIndices = [];
          for (let j = 0; j < transactions.length; j++) {
            if (up.getPluSyaratList().includes(transactions[j].plu)) eligIndices.push(startRow + j);
          }
          const firstEligRow = eligIndices[0];
          const lastEligRow = eligIndices[eligIndices.length - 1];

          if (r === firstEligRow) {
            rowFormulas.push(this.services.upsell.buildCampurSalesTotalFormula(
              up,
              `E${firstEligRow}:E${lastEligRow}`,
              `${lastNetCol}${firstEligRow}:${lastNetCol}${lastEligRow}`,
              `C${up.resultRow}`,
              benefitRef,
              `L${up.resultRow}`
            ));
          } else {
            rowFormulas.push('=0');
          }
          colIdx++;

          if (isEligible) {
            const isLast = (r === lastEligRow);
            const prevRange = `${upPluCol}${firstEligRow}:${upPluCol}${r - 1}`;
            rowFormulas.push(this.services.upsell.buildCampurProrateFormula(
              isLast,
              `${lastNetCol}${r}`,
              `$${lastNetCol}$${firstEligRow}:$${lastNetCol}$${lastEligRow}`,
              `$${upTotalCol}$${firstEligRow}`,
              prevRange,
              `${upTotalCol}${firstEligRow}`
            ));
          } else {
            rowFormulas.push('=0');
          }
          colIdx++;
        } else {
          // Campur = N
          if (isEligible) {
            rowFormulas.push(this.services.upsell.buildNonCampurSalesTotalFormula(
              up,
              `E${r}`,
              `${lastNetCol}${r}`,
              `C${up.resultRow}`,
              benefitRef,
              `L${up.resultRow}`
            ));
            colIdx++;
            rowFormulas.push(`=${upTotalCol}${r}`); colIdx++;
          } else {
            rowFormulas.push('=0'); colIdx++;
            rowFormulas.push('=0'); colIdx++;
          }
        }
        rowFormulas.push(this.services.upsell.buildNetAfterFormula(`${lastNetCol}${r}`, `${upPluCol}${r}`)); colIdx++;
        lastNetCol = netUpCol;
      }

      // Fair Potal
      for (const pot of promoColsDef.fairPotal) {
        const potTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const potPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netPotCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        const eligIndices = [];
        for (let j = 0; j < transactions.length; j++) {
          if (pot.isAllPlu() || pot.getPluSyaratList().includes(transactions[j].plu)) {
            eligIndices.push(startRow + j);
          }
        }
        const firstEligRow = eligIndices[0];
        const lastEligRow = eligIndices[eligIndices.length - 1];
        const isEligible = pot.isAllPlu() || pot.getPluSyaratList().includes(item.plu);
        const benefitRef = pot.rpBenefit ? `E${pot.resultRow}` : `D${pot.resultRow}`;

        if (r === firstEligRow) {
          const eligSum = `SUM(${eligIndices.map(idx => `${lastNetCol}${idx}`).join(',')})`;
          rowFormulas.push(this.services.fairPotal.buildSalesTotalFormula(
            pot,
            eligSum,
            `C${pot.resultRow}`,
            benefitRef,
            `L${pot.resultRow}`
          ));
        } else {
          rowFormulas.push('=0');
        }
        colIdx++;

        if (isEligible) {
          const isBalancing = (r === firstEligRow);
          const otherEligRows = eligIndices.filter(idx => idx !== firstEligRow);
          const balancingRange = otherEligRows.map(idx => `${potPluCol}${idx}`).join(',');
          const eligSumAbs = `SUM(${eligIndices.map(idx => `$${lastNetCol}$${idx}`).join(',')})`;

          rowFormulas.push(this.services.fairPotal.buildProrateFormula(
            isBalancing,
            `${lastNetCol}${r}`,
            eligSumAbs,
            `$${potTotalCol}$${firstEligRow}`,
            balancingRange,
            `${potTotalCol}${firstEligRow}`
          ));
        } else {
          rowFormulas.push('=0');
        }
        colIdx++;

        rowFormulas.push(this.services.fairPotal.buildNetAfterFormula(`${lastNetCol}${r}`, `${potPluCol}${r}`)); colIdx++;
        lastNetCol = netPotCol;
      }

      // Fair TMH / Fair Hadiah
      if (promoColsDef.fairTmh.length > 0 || promoColsDef.fairHadiah.length > 0) {
        const tmhTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const tmhPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netTmhCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        const isFairHadiah = item.packet.toLowerCase().includes('fair hadiah');
        const isFairTMH = item.packet.toLowerCase().includes('tebus murah') || item.packet.toLowerCase().includes('tmh');

        if (isFairHadiah) {
          rowFormulas.push(this.services.fairHadiah.buildSalesFormula(`F${r}`)); colIdx++;
          rowFormulas.push(`=${tmhTotalCol}${r}`); colIdx++;
        } else if (isFairTMH) {
          const matchedTmh = promoColsDef.fairTmh.find(t => t.targetItem.includes(item.plu)) || promoColsDef.fairTmh[0];
          rowFormulas.push(this.services.fairTMH.buildSalesFormula(`E${matchedTmh.resultRow}`, `E${r}`, `${lastNetCol}${r}`)); colIdx++;
          rowFormulas.push(`=${tmhTotalCol}${r}`); colIdx++;
        } else {
          rowFormulas.push('=0'); colIdx++;
          rowFormulas.push('=0'); colIdx++;
        }
        rowFormulas.push(this.services.fairTMH.buildNetAfterFormula(`${lastNetCol}${r}`, `${tmhPluCol}${r}`)); colIdx++;
        lastNetCol = netTmhCol;
      }

      // DAB (Diskon Alat Bayar)
      for (const d of promoColsDef.dab) {
        const dabTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const dabPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netDabCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        if (r === startRow) {
          rowFormulas.push(this.services.dab.buildSalesTotalFormula(
            `SUM(${lastNetCol}${startRow}:${lastNetCol}${endRow})`,
            `L${d.resultRow}`,
            `D${d.resultRow}`
          ));
        } else {
          rowFormulas.push('=0');
        }
        colIdx++;

        rowFormulas.push(this.services.dab.buildSalesProrateFormula(
          `${lastNetCol}${r}`,
          `$${lastNetCol}$${startRow}:$${lastNetCol}$${endRow}`,
          `$${dabTotalCol}$${startRow}`
        ));
        colIdx++;

        rowFormulas.push(this.services.dab.buildNetAfterFormula(`${lastNetCol}${r}`, `${dabPluCol}${r}`)); colIdx++;
        lastNetCol = netDabCol;
      }

      // Point Received
      for (const pt of promoColsDef.points) {
        if (pt.type.toLowerCase().includes('fair')) {
          rowFormulas.push(r === startRow ? this.services.pointStamp.buildFairSalesFormula(`SUM(${lastNetCol}${startRow}:${lastNetCol}${endRow})`, `C${pt.resultRow}`, `F${pt.resultRow}`, `L${pt.resultRow}`) : '=0');
        } else if (pt.type.toLowerCase().includes('cart')) {
          rowFormulas.push(r === startRow ? this.services.pointStamp.buildCartSalesFormula(`SUM(${lastNetCol}${startRow}:${lastNetCol}${endRow})`, `C${pt.resultRow}`, `F${pt.resultRow}`, `L${pt.resultRow}`) : '=0');
        } else {
          // Base
          if (pt.campur === 'Y') {
            const eligIndices = [];
            for (let j = 0; j < transactions.length; j++) {
              if (pt.getPluSyaratList().includes(transactions[j].plu)) eligIndices.push(startRow + j);
            }
            if (eligIndices.length > 0 && r === eligIndices[0]) {
              rowFormulas.push(this.services.pointStamp.buildBaseCampurSalesFormula(`E${eligIndices[0]}:E${eligIndices[eligIndices.length - 1]}`, `C${pt.resultRow}`, `F${pt.resultRow}`, `L${pt.resultRow}`));
            } else {
              rowFormulas.push('=0');
            }
          } else {
            if (pt.getPluSyaratList().includes(item.plu)) {
              rowFormulas.push(this.services.pointStamp.buildBaseNonCampurSalesFormula(`E${r}`, `C${pt.resultRow}`, `F${pt.resultRow}`, `L${pt.resultRow}`));
            } else {
              rowFormulas.push('=0');
            }
          }
        }
        colIdx++;
      }

      // Stamp Received
      for (const st of promoColsDef.stamps) {
        if (st.type.toLowerCase().includes('fair')) {
          rowFormulas.push(r === startRow ? this.services.pointStamp.buildFairSalesFormula(`SUM(${lastNetCol}${startRow}:${lastNetCol}${endRow})`, `C${st.resultRow}`, `F${st.resultRow}`, `L${st.resultRow}`) : '=0');
        } else if (st.type.toLowerCase().includes('cart')) {
          rowFormulas.push(r === startRow ? this.services.pointStamp.buildCartSalesFormula(`SUM(${lastNetCol}${startRow}:${lastNetCol}${endRow})`, `C${st.resultRow}`, `F${st.resultRow}`, `L${st.resultRow}`) : '=0');
        } else {
          // Base
          if (st.campur === 'Y') {
            const eligIndices = [];
            for (let j = 0; j < transactions.length; j++) {
              if (st.getPluSyaratList().includes(transactions[j].plu)) eligIndices.push(startRow + j);
            }
            if (eligIndices.length > 0 && r === eligIndices[0]) {
              rowFormulas.push(this.services.pointStamp.buildBaseCampurSalesFormula(`E${eligIndices[0]}:E${eligIndices[eligIndices.length - 1]}`, `C${st.resultRow}`, `F${st.resultRow}`, `L${st.resultRow}`));
            } else {
              rowFormulas.push('=0');
            }
          } else {
            if (st.getPluSyaratList().includes(item.plu)) {
              rowFormulas.push(this.services.pointStamp.buildBaseNonCampurSalesFormula(`E${r}`, `C${st.resultRow}`, `F${st.resultRow}`, `L${st.resultRow}`));
            } else {
              rowFormulas.push('=0');
            }
          }
        }
        colIdx++;
      }

      formulas.push(rowFormulas);
    }

    return formulas;
  }

  buildSalesTotalRow(sheet, totalRow, startRow, endRow, numCols, promoColsDef) {
    sheet.getRange(totalRow, 5).setValue("Total Gross Sales").setFontWeight("bold");
    sheet.getRange(totalRow, 6).setFormula(`=SUM(F${startRow}:F${endRow})`).setFontWeight("bold");

    // Cari kolom Net Sales terakhir (sebelum Point/Stamp)
    const netDabColIdx = numCols - promoColsDef.points.length - promoColsDef.stamps.length;
    const netDabLetter = ResultSheetBuilder.getColLetter(netDabColIdx);

    sheet.getRange(totalRow, netDabColIdx - 1).setValue("Total Net Sales").setFontWeight("bold");
    sheet.getRange(totalRow, netDabColIdx).setFormula(`=SUM(${netDabLetter}${startRow}:${netDabLetter}${endRow})`).setFontWeight("bold");
  }

  buildDetailTransaksi1(sheet, startRow, salesTotalRow, salesStartRow, salesEndRow, promoColsDef) {
    sheet.getRange(startRow, 1).setValue("Detail Transaksi ").setFontWeight("bold");
    const grossTotalCell = `F${salesTotalRow}`;

    // Diskon Base
    const baseDiscounts = [`SUM(G${salesStartRow}:G${salesEndRow})`];
    // Tambahkan bundling, coret, upsell jika ada
    let c = 9;
    if (promoColsDef.bundling.length > 0) {
      baseDiscounts.push(`SUM(${ResultSheetBuilder.getColLetter(c + 1)}${salesStartRow}:${ResultSheetBuilder.getColLetter(c + 1)}${salesEndRow})`);
      c += 3;
    }
    if (promoColsDef.phg.length > 0) c += 3;
    if (promoColsDef.coret.length > 0) {
      baseDiscounts.push(`SUM(${ResultSheetBuilder.getColLetter(c + 1)}${salesStartRow}:${ResultSheetBuilder.getColLetter(c + 1)}${salesEndRow})`);
      c += 3;
    }
    for (const up of promoColsDef.upsell) {
      baseDiscounts.push(`SUM(${ResultSheetBuilder.getColLetter(c + 1)}${salesStartRow}:${ResultSheetBuilder.getColLetter(c + 1)}${salesEndRow})`);
      c += 3;
    }
    const potalDiscounts = [];
    for (const pot of promoColsDef.fairPotal) {
      potalDiscounts.push(`${ResultSheetBuilder.getColLetter(c)}${salesStartRow}`);
      c += 3;
    }
    const tmhDiscounts = [];
    if (promoColsDef.fairTmh.length > 0 || promoColsDef.fairHadiah.length > 0) {
      tmhDiscounts.push(`SUM(${ResultSheetBuilder.getColLetter(c + 1)}${salesStartRow}:${ResultSheetBuilder.getColLetter(c + 1)}${salesEndRow})`);
      c += 3;
    }
    const dabCell = promoColsDef.dab.length > 0 ? `${ResultSheetBuilder.getColLetter(c)}${salesStartRow}` : '0';

    const details = [
      ["Total Harga", `=${grossTotalCell}`],
      ["Diskon Base", `=${baseDiscounts.join('+')}`],
      ["Fair Potal", potalDiscounts.length > 0 ? `=${potalDiscounts.join('+')}` : '=0'],
      ["Diskon Hadiah & Tebus Murah", tmhDiscounts.length > 0 ? `=${tmhDiscounts.join('+')}` : '=0'],
      ["Total Sebelum DIskon Alat Bayar", `=B${startRow + 1}-B${startRow + 2}-B${startRow + 3}-B${startRow + 4}`],
      ["Diskon Alat Bayar", `=${dabCell}`],
      ["Biaya Pengiriman", "0"],
      ["Biaya Plastik / Packaging", "0"],
      ["Total Pembayaran", `=B${startRow + 5}-B${startRow + 6}+B${startRow + 7}+B${startRow + 8}`]
    ];

    for (let i = 0; i < details.length; i++) {
      const r = startRow + 1 + i;
      sheet.getRange(r, 1).setValue(details[i][0]);
      if (details[i][1].startsWith('=')) {
        sheet.getRange(r, 2).setFormula(details[i][1]);
      } else {
        sheet.getRange(r, 2).setValue(details[i][1]);
      }
    }
    sheet.getRange(startRow + details.length, 1, 1, 2).setFontWeight("bold");
    return startRow + details.length;
  }

  buildFulfillmentFormulas(transactions, promoColsDef, fulfillStartRow, fulfillEndRow, salesStartRow, salesEndRow) {
    const formulas = [];

    for (let i = 0; i < transactions.length; i++) {
      const fr = fulfillStartRow + i;
      const sr = salesStartRow + i;
      const item = transactions[i];
      const rowFormulas = [];

      let colIdx = 1;
      rowFormulas.push(item.packet); colIdx++;
      rowFormulas.push(item.plu); colIdx++;
      rowFormulas.push(`=C${sr}`); colIdx++;
      rowFormulas.push(`=D${sr}`); colIdx++;
      rowFormulas.push(`=E${sr}`); colIdx++;
      rowFormulas.push(item.qtyAktual); colIdx++; // Qty Aktual
      rowFormulas.push(`=D${fr}*F${fr}`); colIdx++; // Gross Sales
      rowFormulas.push(this.services.kartonan.buildDiskonKartonFormula(`B${fr}`, `F${fr}`, item.isKarton)); colIdx++;
      rowFormulas.push(this.services.kartonan.buildNetAfterKartonFormula(`G${fr}`, `H${fr}`)); colIdx++;

      let lastNetCol = 'I';

      // Bundling / PLU
      if (promoColsDef.bundling.length > 0) {
        const bundlingPluCol = ResultSheetBuilder.getColLetter(colIdx);
        const netBundlingCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        rowFormulas.push(this.services.bundling.buildFulfillmentBundlingFormula(`F${fr}`, `E${sr}`, `J${sr}`)); colIdx++;
        rowFormulas.push(this.services.bundling.buildNetAfterBundlingFormula(`${lastNetCol}${fr}`, `${bundlingPluCol}${fr}`)); colIdx++;
        lastNetCol = netBundlingCol;
      }

      // PHG / PLU
      if (promoColsDef.phg.length > 0) {
        const phgPluCol = ResultSheetBuilder.getColLetter(colIdx);
        const netPhgCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        rowFormulas.push(this.services.phg.buildFulfillmentPHGFormula(`F${fr}`, `M${sr}`)); colIdx++;
        rowFormulas.push(this.services.phg.buildNetAfterPHGFormula(`${lastNetCol}${fr}`, `${phgPluCol}${fr}`)); colIdx++;
        lastNetCol = netPhgCol;
      }

      // Harga Coret
      if (promoColsDef.coret.length > 0) {
        const coretPluCol = ResultSheetBuilder.getColLetter(colIdx);
        const netCoretCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const matchedCoret = promoColsDef.coret.find(c => c.getPluSyaratList().includes(item.plu));
        if (matchedCoret) {
          const benefitRef = matchedCoret.rpBenefit ? `E${matchedCoret.resultRow}` : `D${matchedCoret.resultRow}`;
          rowFormulas.push(this.services.hargaCoret.buildFulfillmentFormula(matchedCoret, `F${fr}`, `G${fr}`, `C${matchedCoret.resultRow}`, benefitRef, `L${matchedCoret.resultRow}`));
        } else {
          rowFormulas.push('=0');
        }
        colIdx++;
        rowFormulas.push(this.services.hargaCoret.buildNetAfterFormula(`${lastNetCol}${fr}`, `${coretPluCol}${fr}`)); colIdx++;
        lastNetCol = netCoretCol;
      }

      // Upsell
      for (const up of promoColsDef.upsell) {
        const upTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const upPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netUpCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        const isEligible = up.getPluSyaratList().includes(item.plu);
        if (up.campur === 'Y') {
          const eligIndicesF = [];
          const eligIndicesS = [];
          for (let j = 0; j < transactions.length; j++) {
            if (up.getPluSyaratList().includes(transactions[j].plu)) {
              eligIndicesF.push(fulfillStartRow + j);
              eligIndicesS.push(salesStartRow + j);
            }
          }
          const firstEligF = eligIndicesF[0];
          const lastEligF = eligIndicesF[eligIndicesF.length - 1];
          const firstEligS = eligIndicesS[0];

          if (fr === firstEligF) {
            rowFormulas.push(this.services.upsell.buildCampurFulfillmentTotalFormula(
              `F${firstEligF}:F${lastEligF}`,
              `E${firstEligS}:E${eligIndicesS[eligIndicesS.length - 1]}`,
              `X${firstEligS}`,
              `C${up.resultRow}`,
              `L${up.resultRow}`
            ));
          } else {
            rowFormulas.push('=0');
          }
          colIdx++;

          if (isEligible) {
            const isLast = (fr === lastEligF);
            const prevRange = `${upPluCol}${firstEligF}:${upPluCol}${fr - 1}`;
            rowFormulas.push(this.services.upsell.buildCampurProrateFormula(
              isLast,
              `${lastNetCol}${fr}`,
              `$${lastNetCol}$${firstEligF}:$${lastNetCol}$${lastEligF}`,
              `$${upTotalCol}$${firstEligF}`,
              prevRange,
              `${upTotalCol}${firstEligF}`
            ));
          } else {
            rowFormulas.push('=0');
          }
          colIdx++;
        } else {
          // Campur = N
          if (isEligible) {
            rowFormulas.push(this.services.upsell.buildNonCampurFulfillmentFormula(`F${fr}`, `E${sr}`, `R${sr}`, `C${up.resultRow}`, `L${up.resultRow}`));
            colIdx++;
            rowFormulas.push(`=${upTotalCol}${fr}`); colIdx++;
          } else {
            rowFormulas.push('=0'); colIdx++;
            rowFormulas.push('=0'); colIdx++;
          }
        }
        rowFormulas.push(this.services.upsell.buildNetAfterFormula(`${lastNetCol}${fr}`, `${upPluCol}${fr}`)); colIdx++;
        lastNetCol = netUpCol;
      }

      // Fair Potal
      for (const pot of promoColsDef.fairPotal) {
        const potTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const potPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netPotCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        const eligIndicesF = [];
        const eligIndicesS = [];
        for (let j = 0; j < transactions.length; j++) {
          if (pot.isAllPlu() || pot.getPluSyaratList().includes(transactions[j].plu)) {
            eligIndicesF.push(fulfillStartRow + j);
            eligIndicesS.push(salesStartRow + j);
          }
        }
        const firstEligF = eligIndicesF[0];
        const lastEligF = eligIndicesF[eligIndicesF.length - 1];
        const firstEligS = eligIndicesS[0];
        const isEligible = pot.isAllPlu() || pot.getPluSyaratList().includes(item.plu);

        if (fr === firstEligF) {
          const eligSumF = `SUM(${eligIndicesF.map(idx => `${lastNetCol}${idx}`).join(',')})`;
          rowFormulas.push(this.services.fairPotal.buildFulfillmentTotalFormula(eligSumF, pot.rpMax || 100000, `AD${firstEligS}`));
        } else {
          rowFormulas.push('=0');
        }
        colIdx++;

        if (isEligible) {
          const isBalancing = (fr === firstEligF);
          const otherEligRows = eligIndicesF.filter(idx => idx !== firstEligF);
          const balancingRange = otherEligRows.map(idx => `${potPluCol}${idx}`).join(',');
          const eligSumAbs = `SUM(${eligIndicesF.map(idx => `$${lastNetCol}$${idx}`).join(',')})`;

          rowFormulas.push(this.services.fairPotal.buildFulfillmentProrateFormula(
            isBalancing,
            `${lastNetCol}${fr}`,
            eligSumAbs,
            `$${potTotalCol}$${firstEligF}`,
            balancingRange,
            `${potTotalCol}${firstEligF}`
          ));
        } else {
          rowFormulas.push('=0');
        }
        colIdx++;

        rowFormulas.push(this.services.fairPotal.buildNetAfterFormula(`${lastNetCol}${fr}`, `${potPluCol}${fr}`)); colIdx++;
        lastNetCol = netPotCol;
      }

      // Fair TMH / Hadiah
      if (promoColsDef.fairTmh.length > 0 || promoColsDef.fairHadiah.length > 0) {
        const tmhPluCol = ResultSheetBuilder.getColLetter(colIdx);
        const netTmhCol = ResultSheetBuilder.getColLetter(colIdx + 1);

        const isFairHadiah = item.packet.toLowerCase().includes('fair hadiah');
        const isFairTMH = item.packet.toLowerCase().includes('tebus murah') || item.packet.toLowerCase().includes('tmh');

        if (isFairHadiah) {
          rowFormulas.push(this.services.fairHadiah.buildFulfillmentFormula(`F${fr}`, `AJ${sr}`));
        } else if (isFairTMH) {
          const matchedTmh = promoColsDef.fairTmh.find(t => t.targetItem.includes(item.plu)) || promoColsDef.fairTmh[0];
          rowFormulas.push(this.services.fairTMH.buildFulfillmentFormula(`E${matchedTmh.resultRow}`, `F${fr}`, `${lastNetCol}${fr}`));
        } else {
          rowFormulas.push('=0');
        }
        colIdx++;
        rowFormulas.push(this.services.fairTMH.buildNetAfterFormula(`${lastNetCol}${fr}`, `${tmhPluCol}${fr}`)); colIdx++;
        lastNetCol = netTmhCol;
      }

      // DAB
      for (const d of promoColsDef.dab) {
        const dabTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const dabPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netDabCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        if (fr === fulfillStartRow) {
          rowFormulas.push(this.services.dab.buildFulfillmentTotalFormula(
            `SUM(${lastNetCol}${fulfillStartRow}:${lastNetCol}${fulfillEndRow})`,
            `C${d.resultRow}`,
            `L${d.resultRow}`,
            `SUM(AL${salesStartRow}:AL${salesEndRow})`,
            `AM${salesStartRow}`
          ));
        } else {
          rowFormulas.push('=0');
        }
        colIdx++;

        const isBalancing = (fr === fulfillStartRow);
        const otherRows = [];
        for (let j = 1; j < transactions.length; j++) otherRows.push(`${dabPluCol}${fulfillStartRow + j}`);

        rowFormulas.push(this.services.dab.buildFulfillmentProrateFormula(
          isBalancing,
          `${lastNetCol}${fr}`,
          `$${lastNetCol}$${fulfillStartRow}:$${lastNetCol}$${fulfillEndRow}`,
          `$${dabTotalCol}$${fulfillStartRow}`,
          otherRows.join(','),
          `${dabTotalCol}${fulfillStartRow}`
        ));
        colIdx++;

        rowFormulas.push(this.services.dab.buildNetAfterFormula(`${lastNetCol}${fr}`, `${dabPluCol}${fr}`)); colIdx++;
        lastNetCol = netDabCol;
      }

      // Point Received
      for (const pt of promoColsDef.points) {
        if (pt.type.toLowerCase().includes('fair')) {
          rowFormulas.push(fr === fulfillStartRow ? this.services.pointStamp.buildFairFulfillmentFormula(`SUM(${lastNetCol}${fulfillStartRow}:${lastNetCol}${fulfillEndRow})`, `C${pt.resultRow}`, `F${pt.resultRow}`, `L${pt.resultRow}`) : '=0');
        } else if (pt.type.toLowerCase().includes('cart')) {
          rowFormulas.push(fr === fulfillStartRow ? this.services.pointStamp.buildCartFulfillmentFormula(`SUM(${lastNetCol}${fulfillStartRow}:${lastNetCol}${fulfillEndRow})`, `C${pt.resultRow}`, `F${pt.resultRow}`, `L${pt.resultRow}`) : '=0');
        } else {
          // Base
          if (pt.getPluSyaratList().includes(item.plu)) {
            rowFormulas.push(this.services.pointStamp.buildBaseNonCampurFulfillmentFormula(`F${fr}`, `E${sr}`, `C${pt.resultRow}`, `L${pt.resultRow}`, `AP${sr}`));
          } else {
            rowFormulas.push('=0');
          }
        }
        colIdx++;
      }

      // Stamp Received
      for (const st of promoColsDef.stamps) {
        if (st.type.toLowerCase().includes('fair')) {
          rowFormulas.push(fr === fulfillStartRow ? this.services.pointStamp.buildFairFulfillmentFormula(`SUM(${lastNetCol}${fulfillStartRow}:${lastNetCol}${fulfillEndRow})`, `C${st.resultRow}`, `F${st.resultRow}`, `L${st.resultRow}`) : '=0');
        } else if (st.type.toLowerCase().includes('cart')) {
          rowFormulas.push(fr === fulfillStartRow ? this.services.pointStamp.buildCartFulfillmentFormula(`SUM(${lastNetCol}${fulfillStartRow}:${lastNetCol}${fulfillEndRow})`, `C${st.resultRow}`, `F${st.resultRow}`, `L${st.resultRow}`) : '=0');
        } else {
          // Base
          if (st.getPluSyaratList().includes(item.plu)) {
            rowFormulas.push(this.services.pointStamp.buildBaseNonCampurFulfillmentFormula(`F${fr}`, `E${sr}`, `C${st.resultRow}`, `L${st.resultRow}`, `AT${sr}`));
          } else {
            rowFormulas.push('=0');
          }
        }
        colIdx++;
      }

      formulas.push(rowFormulas);
    }

    return formulas;
  }

  buildFulfillmentTotalRow(sheet, totalRow, startRow, endRow, numCols, promoColsDef) {
    sheet.getRange(totalRow, 6).setValue("Total Gross Sales").setFontWeight("bold");
    sheet.getRange(totalRow, 7).setFormula(`=SUM(G${startRow}:G${endRow})`).setFontWeight("bold");

    const netDabColIdx = numCols - promoColsDef.points.length - promoColsDef.stamps.length;
    const netDabLetter = ResultSheetBuilder.getColLetter(netDabColIdx);

    sheet.getRange(totalRow, netDabColIdx - 1).setValue("Total Net Sales").setFontWeight("bold");
    sheet.getRange(totalRow, netDabColIdx).setFormula(`=SUM(${netDabLetter}${startRow}:${netDabLetter}${endRow})`).setFontWeight("bold");
  }

  buildRefundFormulas(transactions, promoColsDef, refundStartRow, refundEndRow, salesStartRow, fulfillStartRow) {
    const formulas = [];

    for (let i = 0; i < transactions.length; i++) {
      const rr = refundStartRow + i;
      const sr = salesStartRow + i;
      const fr = fulfillStartRow + i;
      const item = transactions[i];
      const rowFormulas = [];

      let colIdx = 1;
      rowFormulas.push(item.packet); colIdx++;
      rowFormulas.push(item.plu); colIdx++;
      rowFormulas.push(`=C${sr}`); colIdx++;
      rowFormulas.push(`=D${sr}`); colIdx++;
      rowFormulas.push(`=E${sr}`); colIdx++;
      rowFormulas.push(`=E${rr}-F${fr}`); colIdx++; // Qty Refund
      rowFormulas.push(`=D${rr}*F${rr}`); colIdx++; // Gross Sales
      rowFormulas.push(`=G${sr}-H${fr}`); colIdx++; // Diskon Karton
      rowFormulas.push(`=G${rr}-H${rr}`); colIdx++; // Net After Karton

      let lastNetCol = 'I';

      // Bundling / PLU
      if (promoColsDef.bundling.length > 0) {
        const bundlingPluCol = ResultSheetBuilder.getColLetter(colIdx);
        const netBundlingCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        rowFormulas.push(`=J${sr}-J${fr}`); colIdx++;
        rowFormulas.push(`=${lastNetCol}${rr}-${bundlingPluCol}${rr}`); colIdx++;
        lastNetCol = netBundlingCol;
      }

      // PHG / PLU
      if (promoColsDef.phg.length > 0) {
        const phgPluCol = ResultSheetBuilder.getColLetter(colIdx);
        const netPhgCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        rowFormulas.push(`=M${sr}-L${fr}`); colIdx++;
        rowFormulas.push(`=${lastNetCol}${rr}-${phgPluCol}${rr}`); colIdx++;
        lastNetCol = netPhgCol;
      }

      // Harga Coret
      if (promoColsDef.coret.length > 0) {
        const coretPluCol = ResultSheetBuilder.getColLetter(colIdx);
        const netCoretCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        rowFormulas.push(`=P${sr}-N${fr}`); colIdx++;
        rowFormulas.push(`=${lastNetCol}${rr}-${coretPluCol}${rr}`); colIdx++;
        lastNetCol = netCoretCol;
      }

      // Upsell
      let sUpCol = 18; // Col R in sales
      let fUpCol = 16; // Col P in fulfill
      for (const up of promoColsDef.upsell) {
        const upTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const upPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netUpCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        const sColLetter = ResultSheetBuilder.getColLetter(sUpCol + 1); // Upsell / PLU in sales
        const fColLetter = ResultSheetBuilder.getColLetter(fUpCol + 1); // Upsell / PLU in fulfill

        rowFormulas.push(`=0`); colIdx++;
        rowFormulas.push(`=${sColLetter}${sr}-${fColLetter}${fr}`); colIdx++;
        rowFormulas.push(`=${lastNetCol}${rr}-${upPluCol}${rr}`); colIdx++;
        lastNetCol = netUpCol;
        sUpCol += 3;
        fUpCol += 3;
      }

      // Fair Potal
      let sPotCol = sUpCol;
      let fPotCol = fUpCol;
      for (const pot of promoColsDef.fairPotal) {
        const potTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const potPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netPotCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        const sColLetter = ResultSheetBuilder.getColLetter(sPotCol + 1);
        const fColLetter = ResultSheetBuilder.getColLetter(fPotCol + 1);

        rowFormulas.push(`=0`); colIdx++;
        rowFormulas.push(`=${sColLetter}${sr}-${fColLetter}${fr}`); colIdx++;
        rowFormulas.push(`=${lastNetCol}${rr}-${potPluCol}${rr}`); colIdx++;
        lastNetCol = netPotCol;
        sPotCol += 3;
        fPotCol += 3;
      }

      // Fair TMH / Hadiah
      if (promoColsDef.fairTmh.length > 0 || promoColsDef.fairHadiah.length > 0) {
        const tmhPluCol = ResultSheetBuilder.getColLetter(colIdx);
        const netTmhCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        rowFormulas.push(`=AK${sr}-AH${fr}`); colIdx++;
        rowFormulas.push(`=${lastNetCol}${rr}-${tmhPluCol}${rr}`); colIdx++;
        lastNetCol = netTmhCol;
      }

      // DAB
      for (const d of promoColsDef.dab) {
        const dabTotalCol = ResultSheetBuilder.getColLetter(colIdx);
        const dabPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
        const netDabCol = ResultSheetBuilder.getColLetter(colIdx + 2);

        if (rr === refundStartRow) {
          rowFormulas.push(`=AM${salesStartRow}-AJ${fulfillStartRow}`);
        } else {
          rowFormulas.push('=0');
        }
        colIdx++;

        rowFormulas.push(this.services.dab.buildRefundProrateFormula(
          `${lastNetCol}${rr}`,
          `$${lastNetCol}$${refundStartRow}:$${lastNetCol}$${refundEndRow}`,
          `$${dabTotalCol}$${refundStartRow}`
        ));
        colIdx++;

        rowFormulas.push(this.services.dab.buildNetAfterFormula(`${lastNetCol}${rr}`, `${dabPluCol}${rr}`)); colIdx++;
        lastNetCol = netDabCol;
      }

      // Point
      for (const pt of promoColsDef.points) {
        rowFormulas.push(`=0`); colIdx++;
      }
      // Stamp
      for (const st of promoColsDef.stamps) {
        rowFormulas.push(`=0`); colIdx++;
      }

      formulas.push(rowFormulas);
    }

    return formulas;
  }

