    const borderStyle = (typeof SpreadsheetApp !== 'undefined' && SpreadsheetApp.BorderStyle) ? SpreadsheetApp.BorderStyle.SOLID : null;
    sheet.getRange(1, 1, dataRows.length + 1, headers.length).setBorder(true, true, true, true, true, true, "#D3D3D3", borderStyle);

    for (let c = 1; c <= headers.length; c++) {
      sheet.autoResizeColumn(c);
    }

    return sheet;
  }
}
