164:       sheet.getRange(editOrderStartRow, 3, len, 1).setFormulas(editOrderSummary.map((it, i) => [`=SUMIF($B$${salesStartRow}:$B$${salesEndRow},A${editOrderStartRow + i},$E$${salesStartRow}:$E$${salesEndRow})`]));
