224:   buildPromoColumnsDefinition(promoRules) {
225:     const cols = {
226:       bundling: promoRules.filter(r => r.type.toLowerCase().includes('bundling')),
227:       phg: promoRules.filter(r => r.type.toLowerCase().includes('phg') || r.type.toLowerCase().includes('produk hadiah')),
228:       coret: promoRules.filter(r => r.type.toLowerCase().includes('coret')),
229:       upsell: promoRules.filter(r => r.type.toLowerCase().includes('upsell')),
230:       fairPotal: promoRules.filter(r => r.type.toLowerCase().includes('fair - potal') || r.type.toLowerCase().includes('fair potal')),
231:       fairHadiah: promoRules.filter(r => r.type.toLowerCase().includes('fair hadiah')),
232:       fairTmh: promoRules.filter(r => r.type.toLowerCase().includes('tebus murah') || r.type.toLowerCase().includes('fair tmh')),
233:       dab: promoRules.filter(r => r.type.toLowerCase().includes('dab') || r.type.toLowerCase().includes('alat bayar')),
234:       points: promoRules.filter(r => r.type.toLowerCase().includes('poin')),
235:       stamps: promoRules.filter(r => r.type.toLowerCase().includes('stamp'))
236:     };
237:     return cols;
238:   }
