318:   buildSalesFormulas(transactions, promoColsDef, startRow, endRow) {
319:     const formulas = [];
320: 
321:     for (let i = 0; i < transactions.length; i++) {
322:       const r = startRow + i;
323:       const item = transactions[i];
324:       const rowFormulas = [];
325: 
326:       let colIdx = 1;
327:       // Col 1: Paket, Col 2: PLU
328:       rowFormulas.push(item.packet); colIdx++;
329:       rowFormulas.push(item.plu); colIdx++;
330:       // Col 3: Judul Produk
331:       rowFormulas.push(`=IFERROR(VLOOKUP(B${r},'PLU Master'!$B:$C, 2, FALSE),"")`); colIdx++;
332:       // Col 4: Harga
333:       rowFormulas.push(`=IFERROR(VLOOKUP(B${r},'PLU Master'!$B:$D, 3, FALSE),0)`); colIdx++;
334:       // Col 5: Qty
335:       rowFormulas.push(item.qtyBeli); colIdx++;
336:       // Col 6: Gross Sales (F)
337:       rowFormulas.push(`=D${r}*E${r}`); colIdx++;
338:       // Col 7: Diskon Karton (G)
339:       rowFormulas.push(this.services.kartonan.buildDiskonKartonFormula(`B${r}`, `E${r}`, item.isKarton)); colIdx++;
340:       // Col 8: Net After Karton (H)
341:       rowFormulas.push(this.services.kartonan.buildNetAfterKartonFormula(`F${r}`, `G${r}`)); colIdx++;
342: 
343:       let lastNetCol = 'H';
344: 
345:       // Bundling (I, J, K)
346:       if (promoColsDef.bundling.length > 0) {
347:         const isBundling = item.packet.toLowerCase().includes('bundling');
348:         const bundlingTotalCol = ResultSheetBuilder.getColLetter(colIdx);
349:         const bundlingPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
350:         const netBundlingCol = ResultSheetBuilder.getColLetter(colIdx + 2);
351: 
352:         if (isBundling) {
353:           // Cari range baris untuk paket bundling ini
354:           const pkgIndices = [];
355:           for (let j = 0; j < transactions.length; j++) {
356:             if (transactions[j].packet === item.packet) pkgIndices.push(startRow + j);
357:           }
358:           const pkgFirstRow = pkgIndices[0];
359:           const pkgLastRow = pkgIndices[pkgIndices.length - 1];
360:           const matchedRule = promoColsDef.bundling.find(b => item.packet.includes(b.code)) || promoColsDef.bundling[0];
361:           const benefitRef = matchedRule.pctBenefit ? `D${matchedRule.resultRow}` : `E${matchedRule.resultRow}`;
362: 
363:           if (r === pkgFirstRow) {
364:             rowFormulas.push(this.services.bundling.buildTotalDiscountFormula(matchedRule, benefitRef, `F${pkgFirstRow}:F${pkgLastRow}`));
365:           } else {
366:             rowFormulas.push('=0');
367:           }
368:           colIdx++;
369: 
370:           const isLast = (r === pkgLastRow);
371:           const prevRange = `${bundlingPluCol}${pkgFirstRow}:${bundlingPluCol}${r - 1}`;
372:           rowFormulas.push(this.services.bundling.buildProrateFormula(
373:             isLast,
374:             `F${r}`,
375:             `$F$${pkgFirstRow}:$F$${pkgLastRow}`,
376:             `$${bundlingTotalCol}$${pkgFirstRow}`,
377:             prevRange
378:           ));
379:           colIdx++;
380:         } else {
381:           rowFormulas.push('=0'); colIdx++;
382:           rowFormulas.push('=0'); colIdx++;
383:         }
384:         rowFormulas.push(this.services.bundling.buildNetAfterBundlingFormula(`${lastNetCol}${r}`, `${bundlingPluCol}${r}`)); colIdx++;
385:         lastNetCol = netBundlingCol;
386:       }
387: 
388:       // PHG (L, M, N)
389:       if (promoColsDef.phg.length > 0) {
390:         const isPHG = item.packet.toLowerCase().includes('phg') || item.packet.toLowerCase().includes('hadiah phg');
391:         const phgTotalCol = ResultSheetBuilder.getColLetter(colIdx);
392:         const phgPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
393:         const netPHGCol = ResultSheetBuilder.getColLetter(colIdx + 2);
394: 
395:         if (isPHG) {
396:           rowFormulas.push(this.services.phg.buildSalesPHGFormula(`F${r}`)); colIdx++;
397:           rowFormulas.push(`=${phgTotalCol}${r}`); colIdx++;
398:         } else {
399:           rowFormulas.push('=0'); colIdx++;
400:           rowFormulas.push('=0'); colIdx++;
401:         }
402:         rowFormulas.push(this.services.phg.buildNetAfterPHGFormula(`${lastNetCol}${r}`, `${phgPluCol}${r}`)); colIdx++;
403:         lastNetCol = netPHGCol;
404:       }
405: 
406:       // Harga Coret (O, P, Q)
407:       if (promoColsDef.coret.length > 0) {
408:         const coretTotalCol = ResultSheetBuilder.getColLetter(colIdx);
409:         const coretPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
410:         const netCoretCol = ResultSheetBuilder.getColLetter(colIdx + 2);
411: 
412:         const matchedCoret = promoColsDef.coret.find(c => c.getPluSyaratList().includes(item.plu));
413:         if (matchedCoret) {
414:           const benefitRef = matchedCoret.rpBenefit ? `E${matchedCoret.resultRow}` : `D${matchedCoret.resultRow}`;
415:           rowFormulas.push(this.services.hargaCoret.buildSalesFormula(
416:             matchedCoret,
417:             `E${r}`,
418:             `F${r}`,
419:             `C${matchedCoret.resultRow}`,
420:             benefitRef,
421:             `L${matchedCoret.resultRow}`
422:           ));
423:           colIdx++;
424:           rowFormulas.push(`=${coretTotalCol}${r}`); colIdx++;
425:         } else {
426:           rowFormulas.push('=0'); colIdx++;
427:           rowFormulas.push('=0'); colIdx++;
428:         }
429:         rowFormulas.push(this.services.hargaCoret.buildNetAfterFormula(`${lastNetCol}${r}`, `${coretPluCol}${r}`)); colIdx++;
430:         lastNetCol = netCoretCol;
431:       }
432: 
433:       // Upsell
434:       for (const up of promoColsDef.upsell) {
435:         const upTotalCol = ResultSheetBuilder.getColLetter(colIdx);
436:         const upPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
437:         const netUpCol = ResultSheetBuilder.getColLetter(colIdx + 2);
438: 
439:         const isEligible = up.getPluSyaratList().includes(item.plu);
440:         const benefitRef = up.rpBenefit ? `E${up.resultRow}` : `D${up.resultRow}`;
441: 
442:         if (up.campur === 'Y') {
443:           // Cari baris-baris eligible
444:           const eligIndices = [];
445:           for (let j = 0; j < transactions.length; j++) {
446:             if (up.getPluSyaratList().includes(transactions[j].plu)) eligIndices.push(startRow + j);
447:           }
448:           const firstEligRow = eligIndices[0];
449:           const lastEligRow = eligIndices[eligIndices.length - 1];
450: 
451:           if (r === firstEligRow) {
452:             rowFormulas.push(this.services.upsell.buildCampurSalesTotalFormula(
453:               up,
454:               `E${firstEligRow}:E${lastEligRow}`,
455:               `${lastNetCol}${firstEligRow}:${lastNetCol}${lastEligRow}`,
456:               `C${up.resultRow}`,
457:               benefitRef,
458:               `L${up.resultRow}`
459:             ));
460:           } else {
461:             rowFormulas.push('=0');
462:           }
463:           colIdx++;
464: 
465:           if (isEligible) {
466:             const isLast = (r === lastEligRow);
467:             const prevRange = `${upPluCol}${firstEligRow}:${upPluCol}${r - 1}`;
468:             rowFormulas.push(this.services.upsell.buildCampurProrateFormula(
469:               isLast,
470:               `${lastNetCol}${r}`,
471:               `$${lastNetCol}$${firstEligRow}:$${lastNetCol}$${lastEligRow}`,
472:               `$${upTotalCol}$${firstEligRow}`,
473:               prevRange,
474:               `${upTotalCol}${firstEligRow}`
475:             ));
476:           } else {
477:             rowFormulas.push('=0');
478:           }
479:           colIdx++;
480:         } else {
481:           // Campur = N
482:           if (isEligible) {
483:             rowFormulas.push(this.services.upsell.buildNonCampurSalesTotalFormula(
484:               up,
485:               `E${r}`,
486:               `${lastNetCol}${r}`,
487:               `C${up.resultRow}`,
488:               benefitRef,
489:               `L${up.resultRow}`
490:             ));
491:             colIdx++;
492:             rowFormulas.push(`=${upTotalCol}${r}`); colIdx++;
493:           } else {
494:             rowFormulas.push('=0'); colIdx++;
495:             rowFormulas.push('=0'); colIdx++;
496:           }
497:         }
498:         rowFormulas.push(this.services.upsell.buildNetAfterFormula(`${lastNetCol}${r}`, `${upPluCol}${r}`)); colIdx++;
499:         lastNetCol = netUpCol;
500:       }
501: 
502:       // Fair Potal
503:       for (const pot of promoColsDef.fairPotal) {
504:         const potTotalCol = ResultSheetBuilder.getColLetter(colIdx);
505:         const potPluCol = ResultSheetBuilder.getColLetter(colIdx + 1);
506:         const netPotCol = ResultSheetBuilder.getColLetter(colIdx + 2);
507: 
508:         const eligIndices = [];
509:         for (let j = 0; j < transactions.length; j++) {
510:           if (pot.isAllPlu() || pot.getPluSyaratList().includes(transactions[j].plu)) {
511:             eligIndices.push(startRow + j);
512:           }
513:         }
514:         const firstEligRow = eligIndices[0];
515:         const lastEligRow = eligIndices[eligIndices.length - 1];
516:         const isEligible = pot.isAllPlu() || pot.getPluSyaratList().includes(item.plu);
517:         const benefitRef = pot.rpBenefit ? `E${pot.resultRow}` : `D${pot.resultRow}`;
518: 
519:         if (r === firstEligRow) {
520:           const eligSum = `SUM(${eligIndices.map(idx => `${lastNetCol}${idx}`).join(',')})`;
521:           rowFormulas.push(this.services.fairPotal.buildSalesTotalFormula(
522:             pot,
523:             eligSum,
524:             `C${pot.resultRow}`,
525:             benefitRef,
526:             `L${pot.resultRow}`
527:           ));
528:         } else {
529:           rowFormulas.push('=0');
530:         }
531:         colIdx++;
532: 
533:         if (isEligible) {
534:           const isBalancing = (r === firstEligRow);
535:           const otherEligRows = eligIndices.filter(idx => idx !== firstEligRow);
536:           const balancingRange = otherEligRows.map(idx => `${potPluCol}${idx}`).join(',');
537:           const eligSumAbs = `SUM(${eligIndices.map(idx => `$${lastNetCol}$${idx}`).join(',')})`;
