6: class KartonanService {
7:   constructor() {}
8: 
9:   /**
10:    * Menghasilkan formula diskon karton untuk suatu baris transaksi.
11:    * @param {string} pluCell - Contoh 'B70'
12:    * @param {string} qtyCell - Contoh 'E70'
13:    * @param {boolean} isKarton - Apakah item ini berstatus kartonan
14:    * @returns {string} Formula atau angka '0'
15:    */
16:   buildDiskonKartonFormula(pluCell, qtyCell, isKarton) {
17:     if (!isKarton) {
18:       return '=0';
19:     }
20:     // FRAC_KRT ada di kolom E (indeks 4 dari B), Diskon Karton (Benefit Rp) ada di kolom H (indeks 7 dari B)
21:     return `=IFERROR(ROUNDDOWN(${qtyCell}/VLOOKUP(${pluCell},'PLU Master'!$B:$E,4,FALSE),0)*VLOOKUP(${pluCell},'PLU Master'!$B:$H,7,FALSE),0)`;
22:   }
23: 
24:   /**
25:    * Menghasilkan formula Net Sales After Karton: Gross Sales - Diskon Karton.
26:    * @param {string} grossCell - Contoh 'F70'
27:    * @param {string} kartonCell - Contoh 'G70'
28:    * @returns {string}
29:    */
30:   buildNetAfterKartonFormula(grossCell, kartonCell) {
31:     return `=${grossCell}-${kartonCell}`;
32:   }
33: }
