46:    */
47:   buildFairFulfillmentFormula(fulfillmentNetRangeSum, minRpCell, benefitPtCell, maxRpCell) {
48:     return `=CEILING(ROUNDDOWN(MIN(${maxRpCell},${fulfillmentNetRangeSum})/${minRpCell},0)*${benefitPtCell},1)`;
