58:   /**
59:    * Formula Point/Stamp pada tabel Refund: Selisih antara Sales dan Fulfillment.
60:    */
61:   buildRefundFormula(salesPtCell, fulfillmentPtCell) {
62:     return `=${salesPtCell}-${fulfillmentPtCell}`;
63:   }
