1: /**
2:  * QtyDistributionService.gs
3:  * Bertanggung jawab mendistribusikan total Qty Aktual / Stok fisik per PLU
4:  * ke masing-masing baris transaksi berdasarkan urutan prioritas pemenuhan:
5:  * 1. Bundling
6:  * 2. Hadiah PHG
7:  * 3. Non-Paket / Upsell
8:  * 4. Fair Hadiah
9:  * 5. Fair Tebus Murah
10:  */
11: 
12: class QtyDistributionService {
13:   constructor() {}
14: 
15:   /**
16:    * Menentukan kategori prioritas dari nama paket.
17:    * Nilai return lebih kecil berarti prioritas lebih tinggi.
18:    */
19:   static getPacketPriority(packetName) {
20:     const p = (packetName || '').toLowerCase();
21:     if (p.includes('bundling')) return 1;
22:     if (p.includes('hadiah phg') || p.includes('phg')) return 2;
23:     if (p.includes('non-paket') || p.includes('upsell') || p === '') return 3;
24:     if (p.includes('fair hadiah')) return 4;
25:     if (p.includes('tebus murah') || p.includes('tmh')) return 5;
26:     return 6;
27:   }
28: 
29:   /**
30:    * Mendistribusikan total stok per PLU ke baris-baris transaksi.
31:    * @param {Array<TransactionItem>} transactions 
32:    * @param {Map<string, number>} stockPerPluMap - Map berisi plu -> total Qty Stok
33:    * @returns {Array<TransactionItem>} transactions yang telah diperbarui qtyAktual-nya
34:    */
35:   distributeStock(transactions, stockPerPluMap) {
36:     // Salin stok agar tidak memodifikasi input asli langsung
37:     const remainingStock = new Map();
38:     for (const [plu, stock] of stockPerPluMap.entries()) {
39:       remainingStock.set(String(plu).trim(), Number(stock) || 0);
40:     }
41: 
42:     // Kelompokkan item berdasarkan prioritas paket
43:     const prioritizedIndices = transactions.map((item, idx) => ({
44:       index: idx,
45:       priority: QtyDistributionService.getPacketPriority(item.packet),
46:       plu: item.plu,
47:       qtyBeli: item.qtyBeli
48:     })).sort((a, b) => a.priority - b.priority);
49: 
50:     // Reset qtyAktual pada semua item
51:     for (const item of transactions) {
52:       item.qtyAktual = 0;
53:     }
54: 
55:     // Alokasikan stok sesuai prioritas
56:     for (const entry of prioritizedIndices) {
57:       const item = transactions[entry.index];
58:       const available = remainingStock.get(item.plu) || 0;
59:       if (available <= 0) {
60:         item.qtyAktual = 0;
61:       } else if (available >= item.qtyBeli) {
62:         item.qtyAktual = item.qtyBeli;
63:         remainingStock.set(item.plu, available - item.qtyBeli);
64:       } else {
65:         item.qtyAktual = available;
66:         remainingStock.set(item.plu, 0);
67:       }
68:     }
69: 
70:     return transactions;
71:   }
72: 
73:   /**
74:    * Menghasilkan ringkasan Edit Order per PLU dari daftar transaksi.
75:    * @param {Array<TransactionItem>} transactions
76:    * @param {Map<string, Product>} productsMap
77:    * @returns {Array<EditOrderRow>}
78:    */
79:   buildEditOrderSummary(transactions, productsMap) {
80:     const summaryMap = new Map();
81: 
82:     for (const item of transactions) {
83:       if (!summaryMap.has(item.plu)) {
84:         const prod = productsMap ? productsMap.get(item.plu) : null;
85:         summaryMap.set(item.plu, {
86:           plu: item.plu,
87:           name: prod ? prod.name : item.name,
88:           qtyBeli: 0,
89:           qtyStok: 0
90:         });
91:       }
92:       const entry = summaryMap.get(item.plu);
93:       entry.qtyBeli += item.qtyBeli;
94:       entry.qtyStok += item.qtyAktual;
95:     }
96: 
97:     const result = [];
98:     for (const entry of summaryMap.values()) {
99:       const qtyRefund = Math.max(0, entry.qtyBeli - entry.qtyStok);
100:       result.push(new EditOrderRow(
101:         entry.plu,
102:         entry.name,
103:         entry.qtyBeli,
104:         entry.qtyStok,
105:         qtyRefund
106:       ));
107:     }
108: 
109:     return result;
110:   }
111: }
