      return `=CEILING(MIN(ROUNDDOWN(SUM(${qtyCell})/${minQtyCell},0)*${minQtyCell},${minQtyCell}*${maxQtyCell})/SUM(${qtyCell})*SUM(${netPrevCell})*${benefitCell},100)`;
